// Validate the tax ID locally BEFORE spending a metered registry API call.
// Most bad input is a typo, and typos are free to catch here.
const q = $input.first().json.query || {};
let taxId = String(q.tax_id || '')
  .toUpperCase()
  .replace(/^[A-Z]{2}/, '')      // strip country prefix if present
  .replace(/[^0-9]/g, '');       // digits only

if (taxId.length < 2 || taxId.length > 10) {
  return [{ json: {
    valid: false,
    found: false,
    message: 'Invalid tax ID. Enter digits only, e.g. 12345678'
  } }];
}
return [{ json: { valid: true, tax_id: taxId } }];

// Defensive mapping of the registry response.
// The upstream API returns inconsistent field names across company types,
// so try several candidate keys per field instead of trusting one shape.
const d = $input.first().json || {};
const get = (...keys) => {
  for (const k of keys) {
    if (d[k] !== undefined && d[k] !== null && d[k] !== '') return d[k];
  }
  return '';
};

const legalName = get('legal_name', 'name', 'company_name');
if (!legalName) {
  return [{ json: {
    found: false,
    message: 'Company not found. Check the tax ID.',
    legal_name: '', tax_id: '', reg_number: '', address: ''
  } }];
}

const address = [get('address', 'street'), get('city', 'locality'), get('county', 'region')]
  .filter(Boolean).join(', ');

return [{ json: {
  found: true,
  message: 'Company found: ' + legalName,
  legal_name: legalName,
  tax_id: String(get('tax_id', 'vat_id')),
  reg_number: get('registration_number', 'reg_number'),
  address: address
} }];

// === Build contract HTML + assign sequential registry number ===
// Node mode: "Run Once for All Items" (default). Do not change.

const b = $('Webhook Contract Request').first().json.body || {};

// --- Shared-secret check against the hidden field posted by the form ---
// NOTE: inject this from an environment variable or a credential.
// Never hardcode the value in the workflow definition.
const SHARED_SECRET = 'REPLACE_WITH_ENV_VAR';
if ((b.secret || '') !== SHARED_SECRET) {
  throw new Error('Invalid secret - request rejected');
}

// --- Sequential contract number: CTR1, CTR2, ... = highest existing + 1 ---
// Scan every cell returned by the registry sheet for a CTR<number> pattern.
let maxN = 0;
for (const r of $('Read Contract Registry').all()) {
  for (const k in r.json) {
    const m = String(r.json[k]).match(/^CTR(\d+)$/i);
    if (m) { const n = parseInt(m[1], 10); if (n > maxN) maxN = n; }
  }
}
const contractNo = 'CTR' + (maxN + 1);

// --- Escape everything that came from user input ---
const esc = (s) => String(s || '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// --- Date: accept yyyy-mm-dd or dd.mm.yyyy; fall back to today in local tz ---
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Bucharest' }));
const p = (n) => String(n).padStart(2, '0');
let contractDate = String(b.contract_date || '').trim();
const mIso = contractDate.match(/^(\d{4})-(\d{2})-(\d{2})/);
if (mIso) { contractDate = mIso[3] + '.' + mIso[2] + '.' + mIso[1]; }
if (!/^\d{2}\.\d{2}\.\d{4}$/.test(contractDate)) {
  contractDate = p(now.getDate()) + '.' + p(now.getMonth() + 1) + '.' + now.getFullYear();
}

// --- Amount with thousands separator ---
const amountNum = parseFloat(
  String(b.amount || '0').replace(/[^0-9.,]/g, '').replace(',', '.')
) || 0;
const amount = amountNum.toLocaleString('en-US');

const signatory = (esc(b.signatory_first_name) + ' ' + esc(b.signatory_last_name)).trim();

// ====================================================================
//  CONTRACT TEMPLATE - edit the text freely.
//  Do NOT remove or rename the {{...}} tokens: data is injected there.
//  Beneficiary details below are placeholders for this public demo.
// ====================================================================
const TEMPLATE = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<style>
  @page { margin: 2cm 2.2cm; }
  body { font-family: 'DejaVu Sans', Arial, sans-serif; font-size: 10.5pt; line-height: 1.45; color: #111; }
  h1 { font-size: 14pt; text-align: center; margin-bottom: 2px; letter-spacing: 1px; }
  .no { text-align: center; margin-top: 0; margin-bottom: 18px; }
  h2 { font-size: 11pt; margin: 14px 0 6px 0; }
  p { margin: 5px 0; text-align: justify; }
  ul { margin: 4px 0 4px 18px; padding: 0; }
  li { margin: 3px 0; text-align: justify; }
  table.signatures { width: 100%; margin-top: 30px; border-collapse: collapse; }
  table.signatures td { width: 50%; vertical-align: top; padding: 4px; }
  .sign-space { height: 70px; }
</style>
</head>
<body>

<h1>SPONSORSHIP AGREEMENT</h1>
<p class="no">No. {{CONTRACT_NO}}, dated {{CONTRACT_DATE}}</p>

<h2>I. PARTIES</h2>

<p>1.1. <strong>{{SPONSOR_NAME}}</strong>, registered office at {{SPONSOR_ADDRESS}},
tax ID {{SPONSOR_TAX_ID}}, company registration no. {{SPONSOR_REG_NO}},
bank account {{SPONSOR_IBAN}} held at {{SPONSOR_BANK}},
represented by {{SPONSOR_SIGNATORY}}, acting as {{SPONSOR_ROLE}},
hereinafter the <strong>Sponsor</strong>,</p>

<p style="text-align:center;">and</p>

<p>1.2. <strong>Example Foundation</strong>, a non-profit organisation,
registered office at 1 Example Street, Example City,
tax ID 00000000, bank account XX00EXAMPLE0000000000000
held at Example Bank, represented by its President,
hereinafter the <strong>Beneficiary</strong>,</p>

<p>have agreed to enter into this sponsorship agreement under the following terms:</p>

<h2>II. SUBJECT</h2>

<p>2.1. The Sponsor grants the Beneficiary a cash sponsorship of
<strong>{{AMOUNT}}</strong>, under the applicable tax-redirection mechanism.</p>

<p>2.2. The funds will be used by the Beneficiary to deliver its programme
activities, in line with its stated mission.</p>

<h2>III. OBLIGATIONS</h2>

<p>3.1. The sponsored amount is transferred to the Beneficiary's account by the
tax authority. The Sponsor must file the applicable declaration within the
statutory deadline.</p>

<p>3.2. The Beneficiary may acknowledge the sponsorship publicly, naming the
Sponsor and the amount, subject to the Sponsor's approval.</p>

<p>3.3. The Beneficiary undertakes to use the funds solely for the stated
purpose and to report on their use.</p>

<p>3.4. The Sponsor undertakes not to direct the Beneficiary's activity,
whether directly or indirectly.</p>

<h2>IV. TERM</h2>

<p>4.1. This agreement enters into force on the date of signature and remains
valid until completion of the programme.</p>

<h2>V. TERMINATION</h2>

<p>5.1. This agreement terminates by operation of law, without the need for
court intervention, if either party:</p>
<ul>
  <li>fails to perform one of the essential obligations set out in section III;</li>
  <li>is declared insolvent or enters liquidation before performance begins;</li>
  <li>assigns its rights and obligations without the other party's consent.</li>
</ul>

<h2>VI. FORCE MAJEURE</h2>

<p>6.1. Neither party is liable for delayed or improper performance caused by
force majeure as defined by law.</p>

<p>6.2. The party invoking force majeure must notify the other within 3 days
and take all reasonable steps to limit its consequences.</p>

<h2>VII. GOVERNING LAW AND DISPUTES</h2>

<p>7.1. The parties will seek to resolve any dispute amicably. Failing that,
the competent courts have jurisdiction.</p>

<h2>VIII. FINAL PROVISIONS</h2>

<p>8.1. Amendments require a written addendum signed by both parties.</p>

<p>8.2. Executed in 2 counterparts, one for each party, on {{CONTRACT_DATE}}.</p>

<table class="signatures">
  <tr>
    <td>
      <strong>SPONSOR</strong><br>
      {{SPONSOR_NAME}}<br>
      {{SPONSOR_SIGNATORY}}<br>
      {{SPONSOR_ROLE}}
      <div class="sign-space"></div>
      _______________________
    </td>
    <td>
      <strong>BENEFICIARY</strong><br>
      Example Foundation<br>
      President
      <div class="sign-space">
        <!-- Signature image is served from a non-public path at runtime.
             Never reference a scanned signature from a public URL. -->
      </div>
      _______________________
    </td>
  </tr>
</table>

</body>
</html>`;

const html = TEMPLATE
  .split('{{CONTRACT_NO}}').join(contractNo)
  .split('{{CONTRACT_DATE}}').join(contractDate)
  .split('{{SPONSOR_NAME}}').join(esc(b.legal_name))
  .split('{{SPONSOR_ADDRESS}}').join(esc(b.address))
  .split('{{SPONSOR_TAX_ID}}').join(esc(b.tax_id))
  .split('{{SPONSOR_REG_NO}}').join(esc(b.reg_number))
  .split('{{SPONSOR_IBAN}}').join(esc(b.iban).toUpperCase().replace(/\s+/g, ''))
  .split('{{SPONSOR_BANK}}').join(esc(b.bank))
  .split('{{SPONSOR_SIGNATORY}}').join(signatory)
  .split('{{SPONSOR_ROLE}}').join(esc(b.role))
  .split('{{AMOUNT}}').join(amount);

// Clean filename: Contract_CTR1_Example-Ltd.pdf
const slug = String(b.legal_name || 'company')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // strip diacritics
  .replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const fileName = 'Contract_' + contractNo + '_' + slug;

return [{
  json: {
    contract_no: contractNo,
    contract_date: contractDate,
    amount: amount,
    legal_name: String(b.legal_name || ''),
    email: String(b.email || ''),
    signatory: signatory,
    file_name: fileName
  },
  binary: {
    index: {
      data: Buffer.from(html, 'utf-8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
}];
